(function () {
      'use strict';
      var nav = document.getElementById('nav');
      var hamburger = (document.getElementById("__legacy_hamburgerBtn") || document.createElement("button"));
      var mobileMenu = (document.getElementById("__legacy_mobileMenu") || document.createElement("div"));

      if (hamburger && mobileMenu) {
        hamburger.addEventListener('click', function () {
          var isOpen = mobileMenu.classList.toggle('open');
          hamburger.setAttribute('aria-expanded', isOpen.toString());
          hamburger.setAttribute('aria-label', isOpen ? 'סגור תפריט' : 'פתח תפריט');
          document.body.style.overflow = isOpen ? 'hidden' : '';
        });
        mobileMenu.querySelectorAll('a').forEach(function (link) {
          link.addEventListener('click', function () {
            var href = link.getAttribute('href');
            if (href === '#newsletter' || href === 'tips.html#newsletter') return;
            mobileMenu.classList.remove('open');
            hamburger.setAttribute('aria-expanded', 'false');
            hamburger.setAttribute('aria-label', 'פתח תפריט');
            document.body.style.overflow = '';
          });
        });
      }
      if (nav) {
        window.addEventListener('scroll', function () {
          nav.classList.toggle('scrolled', window.scrollY > 10);
        }, { passive: true });
      }
      document.addEventListener('keydown', function (e) {
        if (e.key === 'Escape' && mobileMenu && mobileMenu.classList.contains('open')) {
          mobileMenu.classList.remove('open');
          if (hamburger) {
            hamburger.setAttribute('aria-expanded', 'false');
            hamburger.setAttribute('aria-label', 'פתח תפריט');
            hamburger.focus();
          }
          document.body.style.overflow = '';
        }
      });

      /* Hub card previews: crop is CSS-only; lock inner document overflow so no scrollbars (same-origin). */
      function lockHubPreviewDoc(iframe) {
        function run() {
          try {
            var doc = iframe.contentDocument || iframe.contentWindow.document;
            var html = doc.documentElement;
            var body = doc.body;
            if (html) {
              html.style.overflow = 'hidden';
              html.style.overscrollBehavior = 'none';
            }
            if (body) {
              body.style.overflow = 'hidden';
              body.style.overscrollBehavior = 'none';
            }
          } catch (err) {}
        }
        if (iframe.contentDocument && iframe.contentDocument.readyState === 'complete') {
          run();
        } else {
          iframe.addEventListener('load', run);
        }
      }
      document.querySelectorAll('.hub-card__preview iframe').forEach(lockHubPreviewDoc);
    })();

    // ===== SCROLL TO TOP & NAVIGATION PILLS FUNCTIONALITY =====
    (function() {
      const scrollToTopBtn = document.getElementById('scrollToTopBtn');
      const navPills = document.getElementById('navPills');
      const navPillsSidebar = document.getElementById('navPillsSidebar');
      const navPillLinks = document.querySelectorAll('.nav-pills__pill');
      const sidebarPillLinks = document.querySelectorAll('.nav-pills-sidebar__pill');
      const allPillLinks = document.querySelectorAll('.nav-pills__pill, .nav-pills-sidebar__pill');

      const cardTitles = {
        'planning': 'hub-card-title-planning',
        'flightgen': 'hub-card-title-flightgen',
        'weather': 'hub-card-title-weather',
        'calendar': 'hub-card-title-calendar',
        'esim': 'hub-card-title-esim',
        'packing': 'hub-card-title-packing',
        'budget': 'hub-card-title-budget',
        'transport': 'hub-card-title-transport',
        'airport-hotels': 'hub-card-title-airport-hotels',
        'car-rental': 'hub-card-title-car-rental-partners',
        'theme-parks': 'hub-card-title-theme-parks',
        'approvals': 'hub-auth-entry'
      };

      // Show/hide scroll-to-top button and nav pills on scroll
      window.addEventListener('scroll', function() {
        // Show scroll-to-top button after scrolling 300px
        if (window.scrollY > 300) {
          scrollToTopBtn.classList.add('visible');
        } else {
          scrollToTopBtn.classList.remove('visible');
        }

        // Show nav pills after scrolling 400px (mobile)
        if (window.scrollY > 400) {
          navPills.classList.add('visible');
        } else {
          navPills.classList.remove('visible');
        }

        // Show sidebar pills after scrolling 400px (desktop)
        if (window.scrollY > 400) {
          navPillsSidebar.classList.add('visible');
        } else {
          navPillsSidebar.classList.remove('visible');
        }

        // Update active pill based on current section
        updateActivePill();
      }, { passive: true });

      // Scroll to top on button click
      scrollToTopBtn.addEventListener('click', function() {
        window.scrollTo({ top: 0, behavior: 'smooth' });
      });

      // Update active pill based on scroll position
      function updateActivePill() {
        let currentCard = '';
        const cards = document.querySelectorAll('.hub-card, .hub-auth');

        cards.forEach(card => {
          const cardTop = card.getBoundingClientRect().top;
          if (cardTop <= 250) {
            // Get ID from card
            if (card.classList.contains('hub-auth')) {
              currentCard = 'approvals';
            } else {
              const title = card.querySelector('.hub-card__title');
              if (title) {
                const titleId = title.getAttribute('id');
                if (titleId) {
                  // Map title ID back to card type
                  for (let [cardType, titleId2] of Object.entries(cardTitles)) {
                    if (titleId === titleId2) {
                      currentCard = cardType;
                      break;
                    }
                  }
                }
              }
            }
          }
        });

        // Update active state for all pills
        allPillLinks.forEach(pill => {
          pill.classList.remove('active');
          if (pill.getAttribute('data-card') === currentCard) {
            pill.classList.add('active');
          }
        });

        // Remove highlight from all cards
        document.querySelectorAll('.hub-card.highlight, .hub-auth.highlight').forEach(card => {
          card.classList.remove('highlight');
        });
      }

      // Handle pill click - Desktop sidebar
      sidebarPillLinks.forEach(pill => {
        pill.addEventListener('click', function(e) {
          e.preventDefault();
          const href = this.getAttribute('href');
          const target = document.querySelector(href);
          if (target) {
            // Find the card container
            let cardContainer = target.closest('.hub-card, .hub-auth');

            // Scroll to card
            cardContainer.scrollIntoView({ behavior: 'smooth', block: 'start' });

            // Highlight animation
            setTimeout(() => {
              cardContainer.classList.add('highlight');
              setTimeout(() => {
                cardContainer.classList.remove('highlight');
              }, 2000);
            }, 500);

            // Update active state
            allPillLinks.forEach(p => p.classList.remove('active'));
            this.classList.add('active');
          }
        });
      });

      // Handle pill click - Mobile
      navPillLinks.forEach(pill => {
        pill.addEventListener('click', function(e) {
          e.preventDefault();
          const href = this.getAttribute('href');
          const target = document.querySelector(href);
          if (target) {
            // Find the card container
            let cardContainer = target.closest('.hub-card, .hub-auth');

            // Scroll to card
            cardContainer.scrollIntoView({ behavior: 'smooth', block: 'start' });

            // Highlight animation
            setTimeout(() => {
              cardContainer.classList.add('highlight');
              setTimeout(() => {
                cardContainer.classList.remove('highlight');
              }, 2000);
            }, 500);

            // Update active state
            allPillLinks.forEach(p => p.classList.remove('active'));
            this.classList.add('active');
          }
        });
      });
    })();
